/** Storage paths are generated by the server, never from a client's filename. */
export type MediaPurpose = "profile" | "video" | "thumbnail";

const ownerPattern = /^[a-f0-9]{24}$/;
const timestampPattern = "\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}-\\d{3}-UTC";
const directories = {
  profile: "profile-pictures",
  video: "videos",
  thumbnail: "thumbnails",
} as const;

export function mediaUserFolder(ownerId: string, name?: string | null) {
  if (!ownerPattern.test(ownerId)) throw new Error("Invalid media owner");
  const slug =
    (name ?? "")
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .slice(0, 48)
      .replace(/^-+|-+$/g, "") || "user";
  return `/users/${ownerId}-${slug}`;
}

export function mediaTimestamp(date: Date) {
  // UTC keeps names stable across local development and server regions.
  return date
    .toISOString()
    .replace("T", "_")
    .replace(/[:.]/g, "-")
    .replace("Z", "-UTC");
}

export function mediaLocation({
  ownerId,
  name,
  purpose,
  date = new Date(),
  videoId,
}: {
  ownerId: string;
  name?: string | null;
  purpose: MediaPurpose;
  date?: Date;
  videoId?: string;
}) {
  if (purpose === "video" && (!videoId || !ownerPattern.test(videoId)))
    throw new Error("Invalid video ID");
  return {
    folder: `${mediaUserFolder(ownerId, name)}/${directories[purpose]}`,
    fileName: `${ownerId}-${mediaTimestamp(date)}-${purpose === "video" ? videoId : "current"}${purpose === "profile" ? ".webp" : ""}`,
  };
}

/** Read only a path returned by ImageKit's authenticated file-details API. */
export function namedUpload(
  filePath: string | undefined,
  ownerId: string,
  purpose: "video" | "thumbnail",
) {
  if (!ownerPattern.test(ownerId) || !filePath) return null;
  const suffix = purpose === "video" ? "([a-f0-9]{24})" : "(current)";
  const pattern = new RegExp(
    `^/users/${ownerId}-[a-z0-9]+(?:-[a-z0-9]+)*/${directories[purpose]}/${ownerId}-${timestampPattern}-${suffix}$`,
  );
  const match = pattern.exec(filePath);
  return match ? { videoId: purpose === "video" ? match[1] : undefined } : null;
}
